public sealed class Orders : Collection<Order>
{
    public Money Total => Items.Aggregate(Money.Zero, (sum, o) => sum + o.Amount);

    protected override void InsertItem(int index, Order order)
    {
        ArgumentNullException.ThrowIfNull(order);
        if (Items.Count >= MaxOrders) throw new InvalidOperationException("order limit reached");
        base.InsertItem(index, order);
    }

    public IReadOnlyList<Order> AsOrders() => new ReadOnlyCollection<Order>(this);
}
